public interface DiscountStrategy {
    BigDecimal calculateDiscount(BigDecimal amount);
}

public class VpDiscountStrategy implements DiscountStrategy {
    @Override
    public BigDecimal calculateDiscount(BigDecimal amount) {
        return amount.multiply(new BigDecimal("0.20"));
    }
}

public class OrderProcessor {
    private final List<DiscountStrategy> strategies;

    public OrderProcessor(List<DiscountStrategy> strategies) {
        this.strategies = strategies;
    }

    public BigDecimal process(BigDecimal amount) {
        return strategies.stream()
            .map(s -> s.calculateDiscount(amount))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
